// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner, address currentOwner) public {
        vm.assume(currentOwner != address(0));

        bool ok;
        try c.setOwner(currentOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
        vm.prank(currentOwner);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.owner() == newOwner);
    }
}
